export function getOrganizationalMethodTitle(
  section: OrganizationalMethodSection,
  lang: Lang,
): string {
  return section.titles[lang] ?? section.titles.en;
}

export function getOrganizationalMethodBlocks(
  section: OrganizationalMethodSection,
  lang: Lang,
): string[] {
  const blocks = section.blocks[lang];
  if (blocks?.length) return blocks;
  return section.blocks.en;
}
